import java.util.*;
import java.math.*;

public class Main {
    static String to_string(String s) {
        return "\"" + s + "\"";
    }

    static String to_string(char[] s) {
        return to_string(new String(s));
    }

    static String to_string(boolean b) {
        return b ? "true" : "false";
    }

    static String to_string(List<Boolean> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (Boolean b : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(to_string(b));
        }
        res.append("}");
        return res.toString();
    }

    static String to_string(BitSet v, int N) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < N; i++) {
            res.append(v.get(i) ? '1' : '0');
        }
        return res.toString();
    }

    static <T> String to_string(Collection<T> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (T x : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(to_string(x));
        }
        res.append("}");
        return res.toString();
    }

    static <A, B> String to_string(Pair<A, B> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ")";
    }

    static <A, B, C> String to_string(Tuple3<A, B, C> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ", " + to_string(p.third) + ")";
    }

    static <A, B, C, D> String to_string(Tuple4<A, B, C, D> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ", " + to_string(p.third) + ", " + to_string(p.fourth) + ")";
    }

    static void debug_out(Object... args) {
        // No output needed for debugging
    }

    static class Pair<A, B> {
        A first;
        B second;
        Pair(A a, B b) {
            this.first = a;
            this.second = b;
        }
    }

    static class Tuple3<A, B, C> {
        A first;
        B second;
        C third;
        Tuple3(A a, B b, C c) {
            this.first = a;
            this.second = b;
            this.third = c;
        }
    }

    static class Tuple4<A, B, C, D> {
        A first;
        B second;
        C third;
        D fourth;
        Tuple4(A a, B b, C c, D d) {
            this.first = a;
            this.second = b;
            this.third = c;
            this.fourth = d;
        }
    }

    static <T> T mod_inverse(T a, T m) {
        BigInteger A = (BigInteger) a;
        BigInteger M = (BigInteger) m;
        return (T) A.modInverse(M);
    }

    static class ModNumber {
        static class Type {
            long value;
            Type(long v) { this.value = v; }
        }

        long val;
        static class MyMod {
            static long value;
        }

        ModNumber() {
            this.val = 0;
        }

        <U> ModNumber(U x) {
            this.val = normalize(x);
        }

        static long normalize(Object x) {
            long v;
            if (x instanceof Integer) {
                v = (Integer) x;
            } else if (x instanceof Long) {
                v = (Long) x;
            } else if (x instanceof BigInteger) {
                v = ((BigInteger) x).longValue();
            } else {
                v = 0;
            }
            long m = MyMod.value;
            v = v % m;
            if (v < 0) v += m;
            return v;
        }

        long get() {
            return val;
        }

        public String toString() {
            return Long.toString(val);
        }

        ModNumber& operator+=(ModNumber other) {
            val += other.val;
            if (val >= MyMod.value) val -= MyMod.value;
            return this;
        }

        ModNumber& operator-=(ModNumber other) {
            val -= other.val;
            if (val < 0) val += MyMod.value;
            return this;
        }

        ModNumber& operator+=(Object other) {
            return this.operator+=(new ModNumber(other));
        }

        ModNumber& operator-=(Object other) {
            return this.operator-=(new ModNumber(other));
        }

        ModNumber& operator++() {
            return this.operator+=(1);
        }

        ModNumber& operator--() {
            return this.operator-=(1);
        }

        ModNumber operator++(int) {
            ModNumber tmp = new ModNumber(this.val);
            this.operator+=(1);
            return tmp;
        }

        ModNumber operator--(int) {
            ModNumber tmp = new ModNumber(this.val);
            this.operator-=(1);
            return tmp;
        }

        ModNumber operator-() {
            return new ModNumber(-val);
        }

        ModNumber& operator*=(ModNumber rhs) {
            long m = MyMod.value;
            long a = this.val;
            long b = rhs.val;
            long result = (a * b) % m;
            this.val = result;
            return this;
        }

        ModNumber& operator/=(ModNumber other) {
            this.operator*=(new ModNumber(mod_inverse(other.val, MyMod.value)));
            return this;
        }

        static boolean operator==(ModNumber lhs, ModNumber rhs) {
            return lhs.val == rhs.val;
        }

        static boolean operator<(ModNumber lhs, ModNumber rhs) {
            return lhs.val < rhs.val;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod_value = sc.nextLong();
        ModNumber.MyMod.value = mod_value;

        List<ModNumber> fact = new ArrayList<>();
        List<ModNumber> inv_fact = new ArrayList<>();
        fact.add(new ModNumber(1));
        inv_fact.add(new ModNumber(1));

        // Lambda for combination
        java.util.function.BiFunction<Integer, Integer, ModNumber> C = (x, y) -> {
            int sz = Math.max(x, y);
            while (fact.size() <= sz) {
                fact.add(fact.get(fact.size() - 1).operator*=(new ModNumber(fact.size())));
                inv_fact.add(new ModNumber(1).operator/=(fact.get(fact.size() - 1)));
            }
            if (y < 0 || y > x) return new ModNumber(0);
            return fact.get(x).operator*=(inv_fact.get(y)).operator*=(inv_fact.get(x - y));
        };

        ModNumber[] ways_arr = new ModNumber[m + 1];
        ModNumber[] ways_count = new ModNumber[m + 1];
        for (int i = 0; i <= m; i++) {
            ways_arr[i] = new ModNumber(0);
            ways_count[i] = new ModNumber(0);
        }
        ways_count[0] = new ModNumber(1);

        for (int i = 1; i <= m; ++i) {
            for (int j = 0; j < i; ++j) {
                int l = j, r = i - 1 - j;
                ModNumber c = C.apply(l + r, l);
                ModNumber add = new ModNumber(l).operator*(new ModNumber(l + 1)).operator+ (new ModNumber(r).operator*(new ModNumber(r + 1))).operator/(2);
                ways_arr[i].operator+=(ways_count[l].operator*=(ways_count[r]).operator*=(c).operator*=(add));
            }
            for (int j = 0; j < i; ++j) {
                int l = j, r = i - 1 - j;
                ModNumber add = new ModNumber(l).operator*(new ModNumber(l + 1)).operator+ (new ModNumber(r).operator*(new ModNumber(r + 1))).operator/(2);
                ways_count[i].operator+=(ways_count[l].operator*=(ways_count[r]).operator*=(C.apply(l + r, l)).operator*=(add));
            }
        }

        ModNumber[][] dp = new ModNumber[n + 1][m + 1];
        ModNumber[][] ways_dp = new ModNumber[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new ModNumber(0);
                ways_dp[i][j] = new ModNumber(0);
            }
        }
        ways_dp[0][0] = new ModNumber(1);

        for (int i = 1; i <= n; ++i) {
            for (int s = 0; s <= Math.min(m, i); ++s) {
                if (s == i) {
                    dp[i][s] = ways_count[s];
                    continue;
                }
                for (int d = 1; d <= s + 1; ++d) {
                    ModNumber ft = dp[i - d][s + 1 - d];
                    ModNumber way = ways_dp[i - d][s + 1 - d];
                    int add = d - 1;
                    ways_dp[i][s].operator+=(way.operator*=(ways_count[add]).operator*=(C.apply(s, add)));
                    dp[i][s].operator+=(way.operator*=(ways_count[add]).operator*=(C.apply(s, add)).operator+ (ft.operator*=(ways_count[add])));
                }
            }
        }

        System.out.println(dp[n][m]);
    }
}

